/*
 * Aura Theme — Sidebar & Navbar Vue Components
 * Rewrtten from DataValue Theme 15 minified bundle
 * Author: Yousef Ashraf
 */

(function () {
    'use strict';

    if (typeof Vue === 'undefined') return;

    /* ================================================================
       Helpers
    ================================================================ */
    function get_body_data(key) {
        return document.body.getAttribute('data-' + key) || '';
    }

    function icon_html(icon) {
        if (!icon) return '<i class="far fa-circle"></i>';
        if (icon.startsWith('fa') || icon.startsWith('fal') || icon.startsWith('fas') || icon.startsWith('far')) {
            return '<i class="' + icon + '"></i>';
        }
        if (icon.startsWith('/') || icon.startsWith('http')) {
            return '<img src="' + icon + '" style="width:18px;height:18px;object-fit:contain;" />';
        }
        return (
            '<svg class="icon icon-sm"><use href="#icon-' + icon + '"></use></svg>'
        );
    }

    /* ================================================================
       Side Menu Component
    ================================================================ */
    Vue.component('aura-side-menu', {
        template: '#aura-side-menu-template',
        data: function () {
            return {
                modules:            [],
                active_module:      null,
                active_workspace:   null,
                show_modules:       false,
                always_close_sub:   get_body_data('close-sub-menu') === '1',
                menu_opening_type:  get_body_data('menu-opening-type') || 'Workspace',
                show_icon_label:    false,
                hide_icon_tooltip:  false,
            };
        },
        computed: {
            active_module_links: function () {
                if (!this.active_module) return [];
                return this.active_module.links || [];
            }
        },
        methods: {
            load_modules: function () {
                var self = this;
                var boot_workspaces = (frappe.boot && frappe.boot.allowed_workspaces) || [];
                self.modules = boot_workspaces.filter(function (ws) {
                    return ws.for_user === '' || ws.for_user === frappe.session.user;
                });

                frappe.call({
                    method: 'aura_theme.api.get_theme_settings',
                    callback: function (r) {
                        if (r && r.message) {
                            self.show_icon_label   = r.message.show_icon_label   === '1';
                            self.hide_icon_tooltip = r.message.hide_icon_tooltip === '1';
                        }
                    }
                });
            },

            set_active_module: function (module) {
                if (this.active_module && this.active_module.name === module.name) {
                    this.active_module = null;
                    return;
                }
                this.active_module = module;
                this.show_modules  = false;
                // Navigate
                if (this.menu_opening_type === 'Dashboard') {
                    frappe.set_route('dashboard-view', module.name);
                } else {
                    frappe.set_route('Workspaces', module.name);
                }
            },

            get_icon_html: function (icon) {
                return icon_html(icon);
            },

            toggle_modules_overlay: function () {
                this.show_modules = !this.show_modules;
            }
        },
        mounted: function () {
            this.load_modules();

            var self = this;
            $(document).on('page-change.aura-sidebar', function () {
                var route = frappe.get_route();
                if (route && route[0] === 'Workspaces' && route[1]) {
                    var ws_name = route[1];
                    var found = self.modules.find(function (m) {
                        return m.name === ws_name || m.title === ws_name;
                    });
                    if (found) self.active_module = found;
                }
            });
        },
        beforeDestroy: function () {
            $(document).off('page-change.aura-sidebar');
        }
    });

    /* ================================================================
       Side Menu Template (injected as script tag)
    ================================================================ */
    var tmpl = document.createElement('script');
    tmpl.type = 'text/x-template';
    tmpl.id   = 'aura-side-menu-template';
    tmpl.textContent = `
<div class="side-menu">

  <!-- Icon strip -->
  <div class="side-menu-icons">
    <ul>
      <li v-for="module in modules"
          :key="module.name"
          :class="{ active: active_module && active_module.name === module.name }"
          :title="!hide_icon_tooltip ? (module.title || module.name) : ''">
        <a href="#" @click.prevent="set_active_module(module)">
          <span class="animated-tada">
            <span class="animated-icon" v-html="get_icon_html(module.icon)"></span>
          </span>
          <span class="icon-label" v-if="show_icon_label">{{ module.title || module.name }}</span>
        </a>
      </li>
    </ul>
  </div>

  <!-- Items panel -->
  <div class="side-menu-items" v-show="active_module">
    <div class="side-menu-items-header" v-if="active_module">
      <span v-html="get_icon_html(active_module.icon)"></span>
      <span class="module-title">{{ active_module.title || (active_module.name) }}</span>
    </div>
    <ul class="dropdown-list" v-if="active_module">
      <template v-for="link in active_module_links">
        <!-- Section label -->
        <li v-if="link.type === 'Card Break' || link.type === 'card_break'"
            :key="'break-' + link.label"
            class="dropdown-header">
          <span>{{ link.label }}</span>
        </li>
        <!-- Regular link -->
        <li v-else :key="link.name || link.label" class="has-sub">
          <a :href="frappe.utils.get_form_link(link.link_type, link.link_to)"
             @click.prevent="navigate(link)">
            <span v-html="get_icon_html(link.icon)"></span>
            <span class="link-title">{{ link.label || link.link_to }}</span>
          </a>
        </li>
      </template>
    </ul>
  </div>

  <!-- Modules overlay -->
  <div class="modules-menu" v-show="show_modules">
    <ul class="modules-menu-list">
      <li v-for="module in modules" :key="'ov-' + module.name">
        <a href="#" @click.prevent="set_active_module(module)">
          <span v-html="get_icon_html(module.icon)"></span>
          <span>{{ module.title || module.name }}</span>
        </a>
      </li>
    </ul>
  </div>

</div>
    `;
    document.head.appendChild(tmpl);

    /* Navigate method — attach to prototype since template has it */
    Vue.prototype.navigate = function (link) {
        if (!link) return;
        const type = link.link_type || link.type;
        const to   = link.link_to;
        if (!to) return;
        if (type === 'DocType') {
            frappe.set_route('List', to);
        } else if (type === 'Report') {
            frappe.set_route('query-report', to);
        } else if (type === 'Page') {
            frappe.set_route(to);
        } else if (type === 'Workspace') {
            frappe.set_route('Workspaces', to);
        } else {
            frappe.set_route('List', to);
        }
    };

    /* ================================================================
       Mount Side Menu on #side-menu-component
    ================================================================ */
    document.addEventListener('DOMContentLoaded', function () {
        var el = document.getElementById('side-menu-component');
        if (!el) return;

        $(document).on('app-loaded', function () {
            if (window.__aura_sidebar_mounted) return;
            window.__aura_sidebar_mounted = true;

            new Vue({
                el: '#side-menu-component',
                template: '<aura-side-menu></aura-side-menu>'
            });

            // niceScroll on sidebar lists
            setTimeout(function () {
                if ($.fn.niceScroll) {
                    $('.side-menu .side-menu-icons > ul').niceScroll({
                        cursorcolor: 'rgba(0,0,0,0.3)',
                        cursorborder: '0px',
                        cursorwidth: '3px'
                    });
                }
            }, 800);
        });
    });

    /* ================================================================
       Navbar injection — adds extra buttons into Frappe's native navbar
    ================================================================ */
    $(document).on('app-loaded', function () {
        if (window.__aura_navbar_injected) return;
        window.__aura_navbar_injected = true;

        // Wait for Frappe's navbar to render
        setTimeout(function () {
            inject_navbar_extras();
        }, 300);
    });

    function inject_navbar_extras() {
        // Try to find Frappe's navbar right section
        var $navbar = $('header.navbar, .navbar');
        if (!$navbar.length) return;

        var is_dark = document.documentElement.getAttribute('data-theme') === 'dark';

        /* ---- Build extras HTML ---- */
        var extras_html = `
<div class="aura-navbar-extras" id="aura-navbar-extras">

  <!-- Enhanced Search -->
  <div class="aura-search-wrapper" id="aura-search-wrapper">
    <button class="aura-search-trigger aura-nav-icon-btn" id="aura-search-trigger" title="Search (Ctrl+K)">
      <i class="fas fa-search"></i>
    </button>
    <div class="aura-search-box">
      <input type="text" class="aura-search-input" id="aura-search-input"
             placeholder="Search... (Ctrl+K)" autocomplete="off" />
      <button class="aura-search-close" id="aura-search-close">
        <i class="fas fa-times"></i>
      </button>
    </div>
  </div>

  <!-- Toggle Full Width -->
  <button class="aura-nav-icon-btn" id="aura-toggle-fullwidth" title="Toggle Sidebar">
    <i class="fas fa-bars-staggered" style="font-size:14px;"></i>
  </button>

  <!-- Dark Mode -->
  <button class="aura-nav-icon-btn" id="aura-dark-mode-btn" title="Toggle Dark Mode">
    <i class="${is_dark ? 'fas fa-sun' : 'fas fa-moon'}"></i>
  </button>

  <!-- Theme Customizer -->
  <button class="aura-nav-icon-btn" id="aura-customizer-btn" title="Theme Customizer">
    <i class="fas fa-palette"></i>
  </button>

</div>`;

        // Inject before the user section in Frappe's navbar
        var $user_section = $('header .navbar-nav, header .header-items, .navbar-collapse');
        if ($user_section.length) {
            $user_section.first().before(extras_html);
        } else {
            // Fallback — append to navbar
            $navbar.first().append(extras_html);
        }

        /* ---- Search bar interactions ---- */
        $(document).on('click', '#aura-search-trigger', function (e) {
            e.preventDefault();
            e.stopPropagation();
            var $w = $('#aura-search-wrapper');
            $w.toggleClass('aura-search-expanded');
            if ($w.hasClass('aura-search-expanded')) {
                setTimeout(function () { $('#aura-search-input').focus(); }, 50);
            }
        });

        $(document).on('click', '#aura-search-close', function (e) {
            e.preventDefault();
            $('#aura-search-wrapper').removeClass('aura-search-expanded');
        });

        // Hook search input into Frappe's awesome bar / search
        $(document).on('input', '#aura-search-input', function () {
            var val = $(this).val();
            if (val.length >= 2) {
                // Delegate to Frappe's search if available
                if (frappe.search && frappe.search.show_results) {
                    frappe.search.show_results(val);
                } else if ($('.search-bar input, .navbar-search input').length) {
                    $('.search-bar input, .navbar-search input').val(val).trigger('input');
                }
            }
        });

        $(document).on('keydown', '#aura-search-input', function (e) {
            if (e.key === 'Escape') {
                $('#aura-search-wrapper').removeClass('aura-search-expanded');
            }
            if (e.key === 'Enter') {
                var val = $(this).val().trim();
                if (val) frappe.set_route('search', val);
                $('#aura-search-wrapper').removeClass('aura-search-expanded');
            }
        });

        // Close search on outside click
        $(document).on('click.aura-search', function (e) {
            if (!$(e.target).closest('#aura-search-wrapper').length) {
                $('#aura-search-wrapper').removeClass('aura-search-expanded');
            }
        });
    }

})();
